contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _dummy) public payable {
        require(_dummy == 0);
        uint balBefore = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        bool isOwner = (c.owner() == address(this));
        assert((!isOwner && reverted && balAfter == balBefore) || (isOwner && balAfter <= balBefore));
    }

    receive() external payable {}
}

