pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _dummy) internal {
        _dummy = 0;
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        bool isOwner = (c.owner() == address(this));
        assertTrue((!isOwner && reverted && balAfter == balBefore) || (isOwner && balAfter <= balBefore));
    }

    function testFuzz_run(uint256 _dummy) public {
        _run(_dummy);
    }

    receive() external payable {}
}
